function students_workspace_url(int $activityId,int $courseId=0,int $cohortId=0,int $studentId=0,string $q='',int $page=1,array $extra=[]): string {$args=['activity'=>$activityId];if($courseId>0)$args['course']=$courseId;if($cohortId>0)$args['cohort']=$cohortId;if($studentId>0)$args['student']=$studentId;if($q!=='')$args['q']=$q;if($page>1)$args['page']=$page;$args+=$extra;return '/admin/students.php?'.http_build_query($args);}
function admin_students_datetime(?string $value): string {if(!$value)return '—';$ts=strtotime($value);return $ts===false?$value:date('d/m/Y · H:i',$ts);}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 if(!verify_csrf('students-admin',$_POST['_csrf']??null)){http_response_code(403);exit('Invalid request');}$action=(string)($_POST['action']??'');
 try{
  if(!$course)throw new RuntimeException('Escolha um curso.');
  if($action==='move_registration'){course_registration_assign_cohort($db,(int)($_POST['submission_id']??0),$courseId,(int)($_POST['target_cohort_id']??0));student_enrollment_reconcile_confirmed($db,$activityId);$_SESSION['admin_students_notice']='Aluno movido para a turma escolhida.';}
  elseif($action==='disable_enrollment'){$enrollmentId=(int)($_POST['enrollment_id']??0);$check=$db->prepare('SELECT e.id FROM course_enrollments e JOIN course_cohorts cc ON cc.id=e.cohort_id WHERE e.id=? AND cc.course_id=?');$check->execute([$enrollmentId,$courseId]);if(!$check->fetchColumn())throw new RuntimeException('Matrícula inválida.');$db->prepare("UPDATE course_enrollments SET status='disabled',updated_at=? WHERE id=?")->execute([utc_now(),$enrollmentId]);$_SESSION['admin_students_notice']='Participação desativada.';}
  else throw new RuntimeException('Ação inválida.');
 }catch(Throwable $e){$_SESSION['admin_students_notice']='Não foi possível concluir: '.$e->getMessage();}
 header('Location: '.students_workspace_url($activityId,$courseId,$cohortId,$studentId),true,303);exit;
}
$notice=(string)($_SESSION['admin_students_notice']??$_SESSION['admin_notice']??'');unset($_SESSION['admin_students_notice'],$_SESSION['admin_notice']);$tone=str_starts_with($notice,'Não foi possível')?'error':'success';
admin_shell_start('students',$course?($cohort?'Alunos · '.(string)$cohort['title']:'Alunos · '.(string)$course['title']):'Alunos',$state,['/assets/admin-operations.css','/assets/admin-teaching.css']);?>
<?php if($notice!==''):?><div class="admin-notice <?=h($tone)?>" role="<?=$tone==='error'?'alert':'status'?>"><?=h($notice)?></div><?php endif;?>
