$where=[];$args=[];if($q!==''){$where[]='(u.name LIKE ? OR u.email LIKE ? OR p.cpf_last4 LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like);}$whereSql=$where?' WHERE '.implode(' AND ',$where):'';$count=$db->prepare('SELECT COUNT(*) FROM student_users u LEFT JOIN student_profiles p ON p.student_id=u.id'.$whereSql);$count->execute($args);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$pageSize));if($page>$pages)$page=$pages;$offset=($page-1)*$pageSize;$stmt=$db->prepare("SELECT u.id,u.name,u.email,u.status,u.activated_at,u.last_login_at,p.cpf_last4,(SELECT COUNT(*) FROM course_enrollments e JOIN course_cohorts cc ON cc.id=e.cohort_id WHERE e.student_id=u.id AND e.status='active' AND cc.status!='archived') active_enrollments FROM student_users u LEFT JOIN student_profiles p ON p.student_id=u.id$whereSql ORDER BY u.name COLLATE NOCASE,u.id LIMIT $pageSize OFFSET $offset");$stmt->execute($args);$rows=$stmt->fetchAll();?>
