$where=["cc.course_id=?","e.status='active'"];$args=[$courseId];if($cohortId>0){$where[]='cc.id=?';$args[]=$cohortId;}if($q!==''){$where[]='(u.name LIKE ? OR u.email LIKE ? OR p.cpf_last4 LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like);}$whereSql=implode(' AND ',$where);$count=$db->prepare("SELECT COUNT(*) FROM course_enrollments e JOIN course_cohorts cc ON cc.id=e.cohort_id JOIN student_users u ON u.id=e.student_id LEFT JOIN student_profiles p ON p.student_id=u.id WHERE $whereSql");$count->execute($args);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$pageSize));if($page>$pages)$page=$pages;$offset=($page-1)*$pageSize;$stmt=$db->prepare("SELECT e.id enrollment_id,e.source_submission_id,e.confirmed_at,u.id student_id,u.name,u.email,u.status account_status,u.activated_at,u.last_login_at,p.cpf_last4,cc.id cohort_id,cc.title cohort_title FROM course_enrollments e JOIN course_cohorts cc ON cc.id=e.cohort_id JOIN student_users u ON u.id=e.student_id LEFT JOIN student_profiles p ON p.student_id=u.id WHERE $whereSql ORDER BY u.name COLLATE NOCASE,u.id LIMIT $pageSize OFFSET $offset");$stmt->execute($args);$rows=$stmt->fetchAll();$selected=null;if($studentId>0){foreach($rows as $candidate)if((int)$candidate['student_id']===$studentId){$selected=$candidate;break;}if(!$selected){$stmt=$db->prepare("SELECT e.id enrollment_id,e.source_submission_id,e.confirmed_at,u.id student_id,u.name,u.email,u.status account_status,u.activated_at,u.last_login_at,p.cpf_last4,cc.id cohort_id,cc.title cohort_title FROM course_enrollments e JOIN course_cohorts cc ON cc.id=e.cohort_id JOIN student_users u ON u.id=e.student_id LEFT JOIN student_profiles p ON p.student_id=u.id WHERE u.id=? AND cc.course_id=? AND e.status='active' ORDER BY e.confirmed_at DESC LIMIT 1");$stmt->execute([$studentId,$courseId]);$selected=$stmt->fetch()?:null;}}
