r aluno</button></form><p><a href="<?=h(registration_admin_url($activityId,$courseId,0,(int)$selected['source_submission_id']))?>">Ver inscrição original</a></p></section><?php endif;?><section class="admin-operation-danger"><h3>Desativar participação</h3><p>Interrompe o acesso por esta matrícula sem apagar o histórico da pessoa.</p><form method="post" data-confirm="Desativar esta participação?"><input type="hidden" name="_csrf" value="<?=h(csrf_token('students-admin'))?>"><input type="hidden" name="action" value="disable_enrollment"><input type="hidden" name="course_id" value="<?=$courseId?>"><input type="hidden" name="cohort_id" value="<?=$cohortId?>"><input type="hidden" name="student" value="<?=$studentId?>"><input type="hidden" name="enrollment_id" value="<?=(int)$selected['enrollment_id']?>"><button class="admin-button danger" type="submit">Desativar participação</button></form></section></section><?php endif;?>
